/**
 * The layout half of console.log's object writer (ld45, 2026-10-24): the WAT helpers that turn
 * already-rendered entries into Deno's text for an object or an array, as `util.inspect` lays it
 * out (Deno's console follows Node's `reduceToSingleString` and `groupArrayElements`).
 *
 * The per-type half — which fields, in which order, rendered how — is generated by wasic.ts
 * (`WasicTranspiler.inspectWritersWat`), which knows the struct and class layouts. Every writer
 * returns a FRESH heap string as `(ptr, len)`; console.log prints it like any other string.
 *
 * The rules, measured against Deno 2026-10-24:
 *   - an object is `{ k: v, … }` on ONE line when no entry holds a newline, fewer than 3 levels of
 *     objects were formatted below it (Node's `ctx.currentDepth - recurseTimes < ctx.compact`),
 *     and `2·n + indent + brace + 10 + Σ width ≤ 80`; else one entry per line, indented 2 more;
 *   - an array is the same with `[ … ]`, after Node's column grouping when it has more than 6
 *     entries (numbers right-aligned, anything else left-aligned); at most 100 entries, then
 *     `... N more items`;
 *   - an empty object is `{}` (a class's `Name {}`), an empty array `[]`.
 *
 *   - a string longer than 16 characters and than `76 − indent` that holds a newline is split
 *     after each newline into quoted pieces joined by ` +` and a new line (formatPrimitive);
 *   - past depth 4 a non-empty value is `[Object]`, `[Name]` or `[Array]`.
 *
 * Node's `ctx.currentDepth` is the global `$__insp_cur`: a writer that formats a non-empty value
 * at depth `lvl` sets it to `lvl` before its entries, and reads `cur − lvl` after them (how deep
 * below it the last value formatted sat), which decides whether it may stay on one line.
 *
 * Depends on `$__malloc`, `$__arr_spaces` and `$__arr_elem_str` (the array print helper) and
 * `$__i32_to_str`.
 *
 * @module
 */

/** The shared layout helpers, given the data offsets of the texts "null" and "[Array]". Include
 *  once; the per-type writers call them. */
export function getInspectHelperWat(nullPtr: number, arrayPtr: number): string {
  return `
  ;; ── console.log's object writer: layout (ld45, src/inspect_wat.ts) ──
  (global $__insp_cur (mut i32) (i32.const 0))
  ;; store (p, l) as entry i of table t
  (func $__insp_put (param $t i32) (param $i i32) (param $p i32) (param $l i32)
    (i32.store (i32.add (local.get $t) (i32.shl (local.get $i) (i32.const 3))) (local.get $p))
    (i32.store offset=4 (i32.add (local.get $t) (i32.shl (local.get $i) (i32.const 3))) (local.get $l))
  )
  ;; "key: " + value, a fresh string
  (func $__insp_kv (param $kp i32) (param $kl i32) (param $vp i32) (param $vl i32) (result i32 i32)
    (local $out i32)
    (local.set $out (call $__malloc (i32.add (local.get $kl) (local.get $vl))))
    (drop (call $__insp_copy (call $__insp_copy (local.get $out) (local.get $kp) (local.get $kl)) (local.get $vp) (local.get $vl)))
    (local.get $out) (i32.add (local.get $kl) (local.get $vl))
  )
  ;; copy len bytes from src to dest; returns dest + len
  (func $__insp_copy (param $dest i32) (param $src i32) (param $len i32) (result i32)
    (memory.copy (local.get $dest) (local.get $src) (local.get $len))
    (i32.add (local.get $dest) (local.get $len))
  )
  ;; a string's display width: its code points (UTF-8 lead bytes)
  (func $__insp_width (param $p i32) (param $l i32) (result i32)
    (local $i i32) (local $w i32)
    (block $done
      (loop $scan
        (br_if $done (i32.ge_u (local.get $i) (local.get $l)))
        (if (i32.ne (i32.and (i32.load8_u (i32.add (local.get $p) (local.get $i))) (i32.const 0xc0)) (i32.const 0x80))
          (then (local.set $w (i32.add (local.get $w) (i32.const 1)))))
        (local.set $i (i32.add (local.get $i) (i32.const 1)))
        (br $scan)))
    (local.get $w)
  )
  ;; 1 if the string holds a newline
  (func $__insp_hasnl (param $p i32) (param $l i32) (result i32)
    (local $i i32)
    (block $done
      (loop $scan
        (br_if $done (i32.ge_u (local.get $i) (local.get $l)))
        (if (i32.eq (i32.load8_u (i32.add (local.get $p) (local.get $i))) (i32.const 10)) (then (return (i32.const 1))))
        (local.set $i (i32.add (local.get $i) (i32.const 1)))
        (br $scan)))
    (i32.const 0)
  )
  ;; a constant string as a fresh heap copy (what an abbreviated value or "null" returns)
  (func $__insp_lit (param $p i32) (param $l i32) (result i32 i32)
    (local $out i32)
    (local.set $out (call $__malloc (local.get $l)))
    (drop (call $__insp_copy (local.get $out) (local.get $p) (local.get $l)))
    (local.get $out) (local.get $l)
  )
  ;; An OBJECT from its n rendered entries "key: value" (table: n (ptr, len) pairs), its opening
  ;; brace text b0 ("{" or "Name {"), its indent, and rel (levels formatted below it).
  (func $__insp_obj (param $t i32) (param $n i32) (param $b0p i32) (param $b0l i32) (param $ind i32) (param $rel i32) (result i32 i32)
    (local $i i32) (local $sum i32) (local $wsum i32) (local $nl i32) (local $single i32)
    (local $out i32) (local $q i32) (local $ep i32) (local $el i32)
    (if (i32.eqz (local.get $n))
      (then
        (local.set $out (call $__malloc (i32.add (local.get $b0l) (i32.const 1))))
        (local.set $q (call $__insp_copy (local.get $out) (local.get $b0p) (local.get $b0l)))
        (i32.store8 (local.get $q) (i32.const 125)) ;; "}"
        (return (local.get $out) (i32.add (local.get $b0l) (i32.const 1)))))
    (block $m_done
      (loop $measure
        (br_if $m_done (i32.ge_u (local.get $i) (local.get $n)))
        (local.set $ep (i32.load (i32.add (local.get $t) (i32.shl (local.get $i) (i32.const 3)))))
        (local.set $el (i32.load offset=4 (i32.add (local.get $t) (i32.shl (local.get $i) (i32.const 3)))))
        (local.set $sum (i32.add (local.get $sum) (local.get $el)))
        (local.set $wsum (i32.add (local.get $wsum) (call $__insp_width (local.get $ep) (local.get $el))))
        (local.set $nl (i32.or (local.get $nl) (call $__insp_hasnl (local.get $ep) (local.get $el))))
        (local.set $i (i32.add (local.get $i) (i32.const 1)))
        (br $measure)))
    (local.set $single (i32.and (i32.and (i32.eqz (local.get $nl)) (i32.lt_s (local.get $rel) (i32.const 3)))
      (i32.le_s (i32.add (i32.add (i32.add (i32.shl (local.get $n) (i32.const 1)) (local.get $ind))
        (i32.add (local.get $b0l) (i32.const 10))) (local.get $wsum)) (i32.const 80))))
    ;; room for the multi-line form, the larger: every entry on its own indented line
    (local.set $out (call $__malloc (i32.add (i32.add (local.get $sum) (local.get $b0l))
      (i32.add (i32.mul (i32.add (local.get $n) (i32.const 1)) (i32.add (local.get $ind) (i32.const 6))) (i32.const 8)))))
    (local.set $q (call $__insp_copy (local.get $out) (local.get $b0p) (local.get $b0l)))
    (if (local.get $single)
      (then (i32.store8 (local.get $q) (i32.const 32)) (local.set $q (i32.add (local.get $q) (i32.const 1))))
      (else
        (i32.store8 (local.get $q) (i32.const 10))
        (local.set $q (call $__arr_spaces (i32.add (local.get $q) (i32.const 1)) (i32.add (local.get $ind) (i32.const 2))))))
    (local.set $i (i32.const 0))
    (block $w_done
      (loop $write
        (br_if $w_done (i32.ge_u (local.get $i) (local.get $n)))
        (if (local.get $i)
          (then
            (i32.store8 (local.get $q) (i32.const 44)) ;; ","
            (if (local.get $single)
              (then (i32.store8 offset=1 (local.get $q) (i32.const 32)) (local.set $q (i32.add (local.get $q) (i32.const 2))))
              (else
                (i32.store8 offset=1 (local.get $q) (i32.const 10))
                (local.set $q (call $__arr_spaces (i32.add (local.get $q) (i32.const 2)) (i32.add (local.get $ind) (i32.const 2))))))))
        (local.set $q (call $__insp_copy (local.get $q)
          (i32.load (i32.add (local.get $t) (i32.shl (local.get $i) (i32.const 3))))
          (i32.load offset=4 (i32.add (local.get $t) (i32.shl (local.get $i) (i32.const 3))))))
        (local.set $i (i32.add (local.get $i) (i32.const 1)))
        (br $write)))
    (if (local.get $single)
      (then (i32.store16 (local.get $q) (i32.const 0x7d20)) (local.set $q (i32.add (local.get $q) (i32.const 2)))) ;; " }"
      (else
        (i32.store8 (local.get $q) (i32.const 10))
        (local.set $q (call $__arr_spaces (i32.add (local.get $q) (i32.const 1)) (local.get $ind)))
        (i32.store8 (local.get $q) (i32.const 125))
        (local.set $q (i32.add (local.get $q) (i32.const 1)))))
    (local.get $out) (i32.sub (local.get $q) (local.get $out))
  )
  ;; An ARRAY from its n rendered entries (table as above), the count of entries not shown
  ;; ($more, past 100), its indent, rel, and whether the entries are numbers ($padStart: grouped
  ;; columns align right). Node's groupArrayElements, then reduceToSingleString.
  (func $__insp_list (param $t i32) (param $n i32) (param $more i32) (param $ind i32) (param $rel i32) (param $padStart i32) (result i32 i32)
    (local $i i32) (local $j i32) (local $c i32) (local $outn i32) (local $sum i32) (local $wsum i32)
    (local $total i32) (local $maxl i32) (local $nl i32) (local $w i32) (local $wt i32) (local $cw i32)
    (local $cols i32) (local $amax i32) (local $bias f64) (local $bmax f64) (local $k i32) (local $last i32)
    (local $mp i32) (local $ml i32) (local $out i32) (local $q i32) (local $single i32) (local $ep i32) (local $el i32)
    (if (i32.and (i32.eqz (local.get $n)) (i32.eqz (local.get $more)))
      (then
        (local.set $out (call $__malloc (i32.const 2)))
        (i32.store16 (local.get $out) (i32.const 0x5d5b)) ;; "[]"
        (return (local.get $out) (i32.const 2))))
    (local.set $outn (i32.add (local.get $n) (i32.ne (local.get $more) (i32.const 0))))
    ;; "... N more item" + "s" when N > 1
    (if (local.get $more)
      (then
        (local.set $mp (call $__malloc (i32.const 32)))
        (i32.store (local.get $mp) (i32.const 0x202e2e2e)) ;; "... "
        (local.set $ml (i32.add (i32.const 4) (call $__i32_to_str (local.get $more) (i32.add (local.get $mp) (i32.const 4)))))
        (i64.store (i32.add (local.get $mp) (local.get $ml)) (i64.const 0x74692065726f6d20)) ;; " more it"
        (i32.store16 offset=8 (i32.add (local.get $mp) (local.get $ml)) (i32.const 0x6d65)) ;; "em"
        (local.set $ml (i32.add (local.get $ml) (i32.const 10)))
        (if (i32.gt_u (local.get $more) (i32.const 1))
          (then (i32.store8 (i32.add (local.get $mp) (local.get $ml)) (i32.const 115)) (local.set $ml (i32.add (local.get $ml) (i32.const 1)))))))
    ;; each entry's width, the sums, the widest
    (local.set $wt (call $__malloc (i32.add (i32.shl (local.get $n) (i32.const 2)) (i32.const 4))))
    (block $m_done
      (loop $measure
        (br_if $m_done (i32.ge_u (local.get $i) (local.get $n)))
        (local.set $ep (i32.load (i32.add (local.get $t) (i32.shl (local.get $i) (i32.const 3)))))
        (local.set $el (i32.load offset=4 (i32.add (local.get $t) (i32.shl (local.get $i) (i32.const 3)))))
        (local.set $w (call $__insp_width (local.get $ep) (local.get $el)))
        (i32.store (i32.add (local.get $wt) (i32.shl (local.get $i) (i32.const 2))) (local.get $w))
        (local.set $sum (i32.add (local.get $sum) (local.get $el)))
        (local.set $wsum (i32.add (local.get $wsum) (local.get $w)))
        (local.set $total (i32.add (local.get $total) (i32.add (local.get $w) (i32.const 2))))
        (if (i32.gt_u (local.get $w) (local.get $maxl)) (then (local.set $maxl (local.get $w))))
        (local.set $nl (i32.or (local.get $nl) (call $__insp_hasnl (local.get $ep) (local.get $el))))
        (local.set $i (i32.add (local.get $i) (i32.const 1)))
        (br $measure)))
    ;; grouping: more than 6 entries, three fit side by side, and many or narrow
    (if (i32.gt_u (local.get $outn) (i32.const 6))
      (then
        (local.set $amax (i32.add (local.get $maxl) (i32.const 2)))
        (if (i32.and (i32.lt_s (i32.add (i32.mul (local.get $amax) (i32.const 3)) (local.get $ind)) (i32.const 80))
                     (i32.or (f64.gt (f64.div (f64.convert_i32_u (local.get $total)) (f64.convert_i32_u (local.get $amax))) (f64.const 5))
                             (i32.le_u (local.get $maxl) (i32.const 6))))
          (then
            (local.set $bias (f64.sqrt (f64.sub (f64.convert_i32_u (local.get $amax))
              (f64.div (f64.convert_i32_u (local.get $total)) (f64.convert_i32_u (local.get $outn))))))
            (local.set $bmax (f64.max (f64.sub (f64.sub (f64.convert_i32_u (local.get $amax)) (f64.const 3)) (local.get $bias)) (f64.const 1)))
            ;; Math.round (half up) of sqrt(2.5 * biasedMax * entries) / biasedMax
            (local.set $cols (i32.trunc_f64_u (f64.floor (f64.add (f64.div
              (f64.sqrt (f64.mul (f64.mul (f64.const 2.5) (local.get $bmax)) (f64.convert_i32_u (local.get $n))))
              (local.get $bmax)) (f64.const 0.5)))))
            (local.set $k (i32.div_s (i32.sub (i32.const 80) (local.get $ind)) (local.get $amax)))
            (if (i32.lt_s (local.get $k) (local.get $cols)) (then (local.set $cols (local.get $k))))
            (if (i32.gt_s (local.get $cols) (i32.const 12)) (then (local.set $cols (i32.const 12))))
            (if (i32.le_s (local.get $cols) (i32.const 1)) (then (local.set $cols (i32.const 0))))))))
    ;; the larger of the forms: every entry on its own line, each padded to the widest column
    (local.set $out (call $__malloc (i32.add (i32.add (local.get $sum) (local.get $ml))
      (i32.add (i32.mul (i32.add (local.get $outn) (i32.const 1)) (i32.add (i32.add (local.get $ind) (local.get $maxl)) (i32.const 10))) (i32.const 8)))))
    (local.set $q (local.get $out))
    (if (local.get $cols)
      (then
        ;; each column's width: its widest entry + 2
        (local.set $cw (call $__malloc (i32.shl (local.get $cols) (i32.const 2))))
        (local.set $c (i32.const 0))
        (block $cw_done
          (loop $cwl
            (br_if $cw_done (i32.ge_u (local.get $c) (local.get $cols)))
            (local.set $w (i32.const 0))
            (local.set $j (local.get $c))
            (block $col_done
              (loop $col
                (br_if $col_done (i32.ge_u (local.get $j) (local.get $n)))
                (local.set $k (i32.load (i32.add (local.get $wt) (i32.shl (local.get $j) (i32.const 2)))))
                (if (i32.gt_u (local.get $k) (local.get $w)) (then (local.set $w (local.get $k))))
                (local.set $j (i32.add (local.get $j) (local.get $cols)))
                (br $col)))
            (i32.store (i32.add (local.get $cw) (i32.shl (local.get $c) (i32.const 2))) (i32.add (local.get $w) (i32.const 2)))
            (local.set $c (i32.add (local.get $c) (i32.const 1)))
            (br $cwl)))
        ;; "[\\n" + indent; rows of cols entries joined ",\\n" + indent; padStart pads before an
        ;; entry, padEnd after its ", "; a row's last entry has no ", "
        (i32.store8 (local.get $q) (i32.const 91))
        (i32.store8 offset=1 (local.get $q) (i32.const 10))
        (local.set $q (call $__arr_spaces (i32.add (local.get $q) (i32.const 2)) (i32.add (local.get $ind) (i32.const 2))))
        (local.set $i (i32.const 0))
        (block $r_done
          (loop $rows
            (br_if $r_done (i32.ge_u (local.get $i) (local.get $n)))
            (if (local.get $i)
              (then
                (i32.store16 (local.get $q) (i32.const 0x0a2c)) ;; ",\\n"
                (local.set $q (call $__arr_spaces (i32.add (local.get $q) (i32.const 2)) (i32.add (local.get $ind) (i32.const 2))))))
            (local.set $last (i32.add (local.get $i) (local.get $cols)))
            (if (i32.gt_u (local.get $last) (local.get $n)) (then (local.set $last (local.get $n))))
            (local.set $j (local.get $i))
            (block $e_done
              (loop $ents
                (br_if $e_done (i32.ge_u (local.get $j) (local.get $last)))
                (local.set $ep (i32.load (i32.add (local.get $t) (i32.shl (local.get $j) (i32.const 3)))))
                (local.set $el (i32.load offset=4 (i32.add (local.get $t) (i32.shl (local.get $j) (i32.const 3)))))
                ;; the padding: the column's width less the entry's and its ", "
                (local.set $k (i32.sub (i32.sub (i32.load (i32.add (local.get $cw) (i32.shl (i32.sub (local.get $j) (local.get $i)) (i32.const 2))))
                  (i32.load (i32.add (local.get $wt) (i32.shl (local.get $j) (i32.const 2))))) (i32.const 2)))
                (if (local.get $padStart) (then (local.set $q (call $__arr_spaces (local.get $q) (local.get $k)))))
                (local.set $q (call $__insp_copy (local.get $q) (local.get $ep) (local.get $el)))
                (if (i32.ne (local.get $j) (i32.sub (local.get $last) (i32.const 1)))
                  (then
                    (i32.store16 (local.get $q) (i32.const 0x202c)) ;; ", "
                    (local.set $q (i32.add (local.get $q) (i32.const 2)))
                    (if (i32.eqz (local.get $padStart)) (then (local.set $q (call $__arr_spaces (local.get $q) (local.get $k)))))))
                (local.set $j (i32.add (local.get $j) (i32.const 1)))
                (br $ents)))
            (local.set $i (local.get $last))
            (br $rows)))
        (if (local.get $more)
          (then
            (i32.store16 (local.get $q) (i32.const 0x0a2c))
            (local.set $q (call $__arr_spaces (i32.add (local.get $q) (i32.const 2)) (i32.add (local.get $ind) (i32.const 2))))
            (local.set $q (call $__insp_copy (local.get $q) (local.get $mp) (local.get $ml)))))
        (i32.store8 (local.get $q) (i32.const 10))
        (local.set $q (call $__arr_spaces (i32.add (local.get $q) (i32.const 1)) (local.get $ind)))
        (i32.store8 (local.get $q) (i32.const 93))
        (return (local.get $out) (i32.sub (i32.add (local.get $q) (i32.const 1)) (local.get $out)))))
    ;; ungrouped: one line when it fits, else one entry per line
    (local.set $single (i32.and (i32.and (i32.eqz (local.get $nl)) (i32.lt_s (local.get $rel) (i32.const 3)))
      (i32.le_s (i32.add (i32.add (i32.add (i32.shl (local.get $outn) (i32.const 1)) (local.get $ind))
        (i32.const 11)) (i32.add (local.get $wsum) (call $__insp_width (local.get $mp) (local.get $ml)))) (i32.const 80))))
    (i32.store8 (local.get $q) (i32.const 91)) ;; "["
    (if (local.get $single)
      (then (i32.store8 offset=1 (local.get $q) (i32.const 32)) (local.set $q (i32.add (local.get $q) (i32.const 2))))
      (else
        (i32.store8 offset=1 (local.get $q) (i32.const 10))
        (local.set $q (call $__arr_spaces (i32.add (local.get $q) (i32.const 2)) (i32.add (local.get $ind) (i32.const 2))))))
    (local.set $i (i32.const 0))
    (block $w_done
      (loop $write
        (br_if $w_done (i32.ge_u (local.get $i) (local.get $outn)))
        (if (local.get $i)
          (then
            (i32.store8 (local.get $q) (i32.const 44))
            (if (local.get $single)
              (then (i32.store8 offset=1 (local.get $q) (i32.const 32)) (local.set $q (i32.add (local.get $q) (i32.const 2))))
              (else
                (i32.store8 offset=1 (local.get $q) (i32.const 10))
                (local.set $q (call $__arr_spaces (i32.add (local.get $q) (i32.const 2)) (i32.add (local.get $ind) (i32.const 2))))))))
        (if (i32.lt_u (local.get $i) (local.get $n))
          (then
            (local.set $q (call $__insp_copy (local.get $q)
              (i32.load (i32.add (local.get $t) (i32.shl (local.get $i) (i32.const 3))))
              (i32.load offset=4 (i32.add (local.get $t) (i32.shl (local.get $i) (i32.const 3)))))))
          (else (local.set $q (call $__insp_copy (local.get $q) (local.get $mp) (local.get $ml)))))
        (local.set $i (i32.add (local.get $i) (i32.const 1)))
        (br $write)))
    (if (local.get $single)
      (then (i32.store16 (local.get $q) (i32.const 0x5d20)) (local.set $q (i32.add (local.get $q) (i32.const 2)))) ;; " ]"
      (else
        (i32.store8 (local.get $q) (i32.const 10))
        (local.set $q (call $__arr_spaces (i32.add (local.get $q) (i32.const 1)) (local.get $ind)))
        (i32.store8 (local.get $q) (i32.const 93))
        (local.set $q (i32.add (local.get $q) (i32.const 1)))))
    (local.get $out) (i32.sub (local.get $q) (local.get $out))
  )
  ;; A string as a value inside an object or an array, at indent ind: quoted as an array element
  ;; is; split after each newline when longer than 16 and than 76 - ind (Node's formatPrimitive)
  (func $__insp_str (param $sp i32) (param $sl i32) (param $ind i32) (result i32 i32)
    (local $w i32) (local $k i32) (local $nls i32) (local $start i32) (local $split i32)
    (local $out i32) (local $q i32) (local $pair i32)
    (local.set $w (call $__insp_width (local.get $sp) (local.get $sl)))
    (block $c_done
      (loop $count
        (br_if $c_done (i32.ge_u (local.get $k) (local.get $sl)))
        (if (i32.eq (i32.load8_u (i32.add (local.get $sp) (local.get $k))) (i32.const 10))
          (then (local.set $nls (i32.add (local.get $nls) (i32.const 1)))))
        (local.set $k (i32.add (local.get $k) (i32.const 1)))
        (br $count)))
    (local.set $split (i32.and (i32.gt_u (local.get $w) (i32.const 16))
      (i32.gt_s (local.get $w) (i32.sub (i32.const 76) (local.get $ind)))))
    ;; each byte at most 4 (an \\xNN escape); each piece 2 quotes, " +\\n" and its indent
    (local.set $out (call $__malloc (i32.add (i32.add (i32.shl (local.get $sl) (i32.const 2)) (i32.const 2))
      (i32.mul (local.get $nls) (i32.add (local.get $ind) (i32.const 8))))))
    (local.set $pair (call $__malloc (i32.const 8)))
    (local.set $q (local.get $out))
    (local.set $k (i32.const 0))
    (if (local.get $split)
      (then
        (block $p_done
          (loop $pieces
            (br_if $p_done (i32.ge_u (local.get $k) (i32.sub (local.get $sl) (i32.const 1))))
            (if (i32.eq (i32.load8_u (i32.add (local.get $sp) (local.get $k))) (i32.const 10))
              (then
                (i32.store (local.get $pair) (i32.add (local.get $sp) (local.get $start)))
                (i32.store offset=4 (local.get $pair) (i32.sub (i32.add (local.get $k) (i32.const 1)) (local.get $start)))
                (local.set $q (i32.add (local.get $q) (call $__arr_elem_str (i32.sub (local.get $pair) (i32.const 8)) (i32.const 0) (i32.const 10) (local.get $q))))
                (i32.store (local.get $q) (i32.const 0x0a2b20)) ;; " +\\n"
                (local.set $q (call $__arr_spaces (i32.add (local.get $q) (i32.const 3)) (i32.add (local.get $ind) (i32.const 2))))
                (local.set $start (i32.add (local.get $k) (i32.const 1)))))
            (local.set $k (i32.add (local.get $k) (i32.const 1)))
            (br $pieces)))))
    (i32.store (local.get $pair) (i32.add (local.get $sp) (local.get $start)))
    (i32.store offset=4 (local.get $pair) (i32.sub (local.get $sl) (local.get $start)))
    (local.set $q (i32.add (local.get $q) (call $__arr_elem_str (i32.sub (local.get $pair) (i32.const 8)) (i32.const 0) (i32.const 10) (local.get $q))))
    (local.get $out) (i32.sub (local.get $q) (local.get $out))
  )
  ;; A scalar at address a (kind as arrInspectKind: 0 i32, 1 f64, 7 f32, 8 boolean, 9 bigint,
  ;; 10 string) as a value at indent ind
  (func $__insp_scalar (param $a i32) (param $kind i32) (param $ind i32) (result i32 i32)
    (local $d i32)
    (if (i32.eq (local.get $kind) (i32.const 10))
      (then (return (call $__insp_str (i32.load (local.get $a)) (i32.load offset=4 (local.get $a)) (local.get $ind)))))
    ;; any number's text fits 32 bytes (an f64 at most 24, an i64 21 with its n)
    (local.set $d (call $__malloc (i32.const 32)))
    (local.get $d) (call $__arr_elem_str (i32.sub (local.get $a) (i32.const 8)) (i32.const 0) (local.get $kind) (local.get $d))
  )
  ;; A SCALAR array (the layouts $__arr_elem_str reads) as a value at indent ind, depth lvl
  (func $__insp_arr_scalar (param $arr i32) (param $kind i32) (param $ind i32) (param $lvl i32) (result i32 i32)
    (local $len i32) (local $n i32) (local $t i32) (local $i i32) (local $sh i32)
    (if (i32.eqz (local.get $arr))
      (then (return (call $__insp_null))))
    (local.set $len (i32.load (local.get $arr)))
    (if (i32.eqz (local.get $len))
      (then (return (call $__insp_list (i32.const 0) (i32.const 0) (i32.const 0) (local.get $ind) (i32.const 0) (i32.const 0)))))
    (if (i32.gt_s (local.get $lvl) (i32.const 4))
      (then (return (call $__insp_lit (i32.const ${arrayPtr}) (i32.const 7)))))
    (global.set $__insp_cur (local.get $lvl))
    (local.set $n (select (i32.const 100) (local.get $len) (i32.gt_u (local.get $len) (i32.const 100))))
    (local.set $t (call $__malloc (i32.add (i32.shl (local.get $n) (i32.const 3)) (i32.const 8))))
    ;; an element's width: 8 bytes for f64, bigint and string, else 4
    (local.set $sh (select (i32.const 3) (i32.const 2)
      (i32.or (i32.eq (local.get $kind) (i32.const 1)) (i32.ge_u (local.get $kind) (i32.const 9)))))
    (block $done
      (loop $each
        (br_if $done (i32.ge_u (local.get $i) (local.get $n)))
        (call $__insp_put (local.get $t) (local.get $i)
          (call $__insp_scalar (i32.add (i32.add (local.get $arr) (i32.const 8)) (i32.shl (local.get $i) (local.get $sh)))
            (local.get $kind) (i32.add (local.get $ind) (i32.const 2))))
        (local.set $i (i32.add (local.get $i) (i32.const 1)))
        (br $each)))
    ;; booleans and strings align LEFT in columns; numbers and bigints right
    (call $__insp_list (local.get $t) (local.get $n) (i32.sub (local.get $len) (local.get $n)) (local.get $ind)
      (i32.sub (global.get $__insp_cur) (local.get $lvl))
      (i32.eqz (i32.or (i32.eq (local.get $kind) (i32.const 8)) (i32.eq (local.get $kind) (i32.const 10)))))
  )
  (func $__insp_null (result i32 i32)
    (call $__insp_lit (i32.const ${nullPtr}) (i32.const 4))
  )`;
}
